function animate(node,frames,timing){const a=node.animate(frames,timing);if(stage._runtime.speed!==1)a.updatePlaybackRate(stage._runtime.speed);owned.add(a);a.finished.then(()=>owned.delete(a),()=>owned.delete(a));return a;}
function ease(t){t=clamp(t,0,1);let lo=0,hi=1,p=t;for(let i=0;i<20;i++){p=(lo+hi)/2;const z=1-p,x=3*z*z*p*.22+3*z*p*p*.36+p*p*p;if(x<t)lo=p;else hi=p;}return 1-Math.pow(1-(lo+hi)/2,3);}
function readout(text,show=true){q('hero-readout').textContent=text;root.dataset.inspecting=String(show);q('status').textContent=text;}
