const arc=q('hero-arc'),pulse=q('hero-pulse'),drawing=motion.slow*2+motion.quick*2/3,holding=motion.quick*4,fading=motion.slow,period=motion.xslow*5,referenceHold=motion.xslow*3;let age=0,last=null,slowHeld=false,hovering=false,focused=false,speed=1,launches=0,manual=false,reference=true;
function paintGlobe(){let opacity=1,progress=1,pulseAmount=-1;if(!reference){const t=age%period;if(t<drawing)progress=t/drawing;else if(t>=drawing+holding)opacity=clamp(1-(t-drawing-holding)/fading,0,1);if(t>=drawing&&t<drawing+holding)pulseAmount=(t-drawing)/holding;}
 arc.style.clipPath=progress===1?'none':'inset(0 '+((1-ease(progress))*100)+'% 0 0)';arc.style.opacity=String(opacity);pulse.setAttribute('r',pulseAmount<0?'0':String(3+11*pulseAmount));pulse.style.opacity=pulseAmount<0?'0':String(1-pulseAmount);Object.assign(root.dataset,{phase:reference?'reference':age%period<drawing?'draw':age%period<drawing+holding?'hold':'fade',progress:String(progress),speed:String(speed),launches:String(launches),slowHeld:String(slowHeld)});}
function frameGlobe(now){const delta=last===null?0:Math.min(50,now-last);last=now;const target=(slowHeld||hovering||focused) ? .4 : 1;speed+=(target-speed)*(1-Math.pow(.95,delta/(1000/60)));age+=delta*speed;if(reference&&!manual){if(age<referenceHold){paintGlobe();nextFrame(frameGlobe);return;}const out=clamp((age-referenceHold)/motion.quick,0,1);arc.style.opacity=String(1-out);if(out<1){nextFrame(frameGlobe);return;}reference=false;age=0;launches++;}paintGlobe();nextFrame(frameGlobe);}
function launchPreview(){if(rm){animate(arc,[{opacity:.25},{opacity:1}],{duration:motion.quick,easing:motion.out});launches++;paintGlobe();return;}const old=arc.cloneNode();old.removeAttribute('data-figma-node');old.classList.add(C+'-retiring');old.style.clipPath=getComputedStyle(arc).clipPath;old.style.opacity=getComputedStyle(arc).opacity;hero.append(old);const a=animate(old,[{opacity:+old.style.opacity},{opacity:0}],{duration:motion.fast,easing:motion.close});a.finished.then(()=>old.remove(),()=>old.remove());while(hero.querySelectorAll('.'+C+'-retiring').length>3){const node=hero.querySelector('.'+C+'-retiring');node.getAnimations().forEach(a=>a.cancel());node.remove();}manual=true;reference=false;age=0;last=null;launches++;paintGlobe();nextFrame(frameGlobe);readout('Illustrative flight arc',true);}
function resetPreview(){cancelAnimationFrame(previewRaf);previewRaf=0;owned.forEach(a=>a.cancel());hero.querySelectorAll('.'+C+'-retiring').forEach(n=>n.remove());age=0;last=null;slowHeld=false;speed=1;launches=0;manual=false;reference=true;readout('',false);paintGlobe();if(!rm)nextFrame(frameGlobe);}
on(hero,'pointerenter',e=>{if(canHover&&e.pointerType!=='touch'){hovering=true;root.dataset.hovering='true';}});on(hero,'pointerleave',()=>{hovering=false;root.dataset.hovering='false';});on(hero,'focus',()=>{focused=true;});on(hero,'blur',()=>{focused=false;});on(hero,'click',launchPreview);on(hero,'keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();launchPreview();}else if(e.key.toLowerCase()==='r'){e.preventDefault();resetPreview();}});
action('replay',resetPreview);action('route',launchPreview);action('slow',()=>{slowHeld=!slowHeld;readout(slowHeld?'Flight inspection speed':'Normal flight speed',true);});exposePreview(()=>({phase:root.dataset.phase,age,speed,launches,reference,slowHeld}),'__mapDotGlobeArcsInspect');paintGlobe();if(!rm)nextFrame(frameGlobe);

